  double edge_width_au{0.015};
  double breakthrough_outer_mass_earth{6.0};
  bool edge_breakthrough_occurred{true};
  double shortest_period_days{4.85};
  double gas_damping_factor_k{10.0};
  double instability_time_myr{18.2};
  bool chain_instability_triggered{true};
  int final_planet_count{3};
